#include "growth_tactic_lesson_boundary.hpp"
#include "growth_tactic_lesson_projection.hpp"
#include "resident/kernel/command_types.hpp"
#include <algorithm>
#include <set>
namespace hanmo::resident {namespace {
using V=BoundaryValue;
bool kind(const StableId& k){return k=="tactic_lesson_started"||k=="tactic_lesson_credit"||k=="tactic_lesson_closed";}
void unique(const V& v,Integer depth=0){if(depth>64)boundary::fail("TacticLessonJSONDepthExceeded","");if(const auto* d=v.as<V::Dict>()){std::set<StableId> names;for(const auto& row:*d){if(!names.insert(row.first).second)boundary::fail("DuplicateTacticLessonJSONField",row.first);unique(row.second,depth+1);}}else if(const auto* a=v.as<V::Array>())for(const auto& row:*a)unique(row,depth+1);}
}
Outcome<bool> decode_growth_tactic_lesson_profile(const V& scenario,const std::vector<StableId>& capabilities){try{using namespace boundary;unique(scenario);const auto* dynamic=scenario.find("dynamic_world");const auto* selected=dynamic?dynamic->find(growth_tactic_lesson_module):nullptr;if(!selected)return {true,false,{}};if(get_string(*dynamic,"profile","dynamic_world")!="local_society_v1")unsupported("TacticLessonDynamicProfileRequired","dynamic_world");for(const auto* cap:{"growth_tactic_lessons_v1","military_tactic_learning_v1","cultivation","dialogue","multi_actor","native_dynamic_world","family_life_v1","family"})if(std::find(capabilities.begin(),capabilities.end(),cap)==capabilities.end())unsupported("TacticLessonCapabilityRequired",cap);if(!scenario.find("family_life"))unsupported("TacticLessonLifeSourceRequired","family_life");const auto* learning=scenario.find("military_tactic_learning");if(!learning||get_int(*learning,"version","military_tactic_learning")!=1)unsupported("TacticLessonMilitaryLearningPairRequired","military_tactic_learning");auto decoded=decode_growth_tactic_lesson_catalog(*selected);if(!decoded.ok)return {false,false,decoded.error};return {true,true,{}};}catch(const boundary::DecodeFailure& e){return {false,false,e.error};}}
Status validate_growth_tactic_lesson_layout(const CommonStore& c,const std::vector<std::pair<StableId,StableId>>& modules,const GrowthTacticLessonCatalog* catalog,const GrowthTacticLessonState* state){Integer selected=0;bool life=false,learning=false,military=false;for(const auto& m:modules){if(m.first==growth_tactic_lesson_module){if(m.second!="1")return common_failure("UnsupportedTacticLessonVersion");++selected;}if(m.first=="family_life"&&m.second=="1")life=true;if(m.first=="military_tactic_learning"&&m.second=="1")learning=true;if(m.first=="military"&&m.second=="16")military=true;}const bool enabled=catalog!=nullptr;if(selected>1||enabled!=(selected==1)||enabled!=(state!=nullptr))return common_failure("TacticLessonProfileMismatch");if(enabled&&(!life||!learning||!military))return common_failure("TacticLessonCompletePairRequired");
 if(!enabled){for(const auto& h:c.state().facts.rows())if(kind(h.second.kind)||h.second.kind.rfind("tactic_lesson_",0)==0||h.second.domain==growth_tactic_lesson_module)return common_failure("TacticLessonProfileRequired",h.first);for(const auto& a:c.state().actions.rows())if(a.second.kind=="tactic_lesson")return common_failure("TacticLessonProfileRequired",a.first);for(const auto& h:c.state().history)if(h.kind.rfind("tactic_lesson_",0)==0)return common_failure("TacticLessonProfileRequired",h.result_id);for(const auto& r:c.state().results.rows())if(r.second&&r.second->kind.rfind("tactic_lesson_",0)==0)return common_failure("TacticLessonProfileRequired",r.first);return common_success();}
 for(const auto& h:c.state().history)if(h.kind.rfind("tactic_lesson_",0)==0&&h.kind!="tactic_lesson_start"&&h.kind!="tactic_lesson_cancel")return common_failure("UnknownTacticLessonCommand",h.kind);for(const auto& r:c.state().results.rows())if(r.second&&r.second->kind.rfind("tactic_lesson_",0)==0&&r.second->kind!="tactic_lesson_start"&&r.second->kind!="tactic_lesson_cancel")return common_failure("UnknownTacticLessonCommand",r.second->kind);return validate_growth_tactic_lesson_shape(*state);
}
Status emit_growth_tactic_lesson_fact_payloads_fields(ProjectionWriter& out,const CommonStore& c,const GrowthTacticLessonState* state){
 if(state){auto checked=validate_growth_tactic_lesson_shape(*state);if(!checked.ok)return checked;out.validate_detached([&](auto& fields){return emit_growth_tactic_lessons_fields(fields,*state);});if(!out.status().ok)return out.status();}
 std::size_t count=0;for(const auto& row:c.state().facts.rows()){const auto& h=row.second;if(!kind(h.kind)&&h.kind.rfind("tactic_lesson_",0)!=0&&h.domain!=growth_tactic_lesson_module)continue;if(!kind(h.kind)||!state||h.id!=row.first||h.domain!=growth_tactic_lesson_module)return common_failure("TacticLessonFactMismatch",row.first);
 const auto* start=state->starts.find(row.first);const auto* credit=state->credits.find(row.first);const auto* closure=state->closures.find(row.first);const auto matches=Integer(bool(start))+Integer(bool(credit))+Integer(bool(closure));if(matches>1)return common_failure("DuplicateTacticLessonPayload",row.first);if(matches!=1||(start?start->kind:credit?credit->kind:closure->kind)!=h.kind)return common_failure("TacticLessonFactMismatch",row.first);
 out.object(row.first,[&](auto& w){auto emitted=start?emit_growth_tactic_lesson_start_fields(w,*start):credit?emit_growth_tactic_lesson_credit_fields(w,*credit):emit_growth_tactic_lesson_closure_fields(w,*closure);if(!emitted.ok)return emitted;w.text("domain",growth_tactic_lesson_module);return w.order_fields(h.field_order);});if(!out.status().ok)return out.status();++count;}
 if(state&&count!=state->starts.size()+state->credits.size()+state->closures.size())return common_failure("TacticLessonFactCoverageMismatch");return out.status();
}
Status emit_growth_tactic_lesson_action_payloads_fields(ProjectionWriter& out,const CommonStore& c,const GrowthTacticLessonState* state){
 for(const auto& row:c.state().actions.rows())if(row.second.kind=="tactic_lesson"){if(!state)return common_failure("TacticLessonProfileRequired",row.first);const GrowthTacticLessonStart* start=nullptr;const StableId* id=nullptr;for(const auto& s:state->starts.rows())if(s.second.action_id==row.first){if(start)return common_failure("DuplicateTacticLessonAction",row.first);start=&s.second;id=&s.first;}if(!start||row.second.id!=row.first||row.second.actor_id!=start->agreement.student_id||row.second.start_tick!=start->agreement.tick)return common_failure("TacticLessonActionMismatch",row.first);for(const auto& e:state->closures.rows())if(e.second.started_fact_id==*id)return common_failure("TacticLessonClosedActionStillLive",row.first);out.object(row.first,[&](auto& w){w.field("definition_id",start->agreement.definition_id);return w.field("started_fact_id",*id);});if(!out.status().ok)return out.status();}return out.status();
}
Outcome<V> growth_tactic_lesson_fact_payloads(const CommonStore& c,const GrowthTacticLessonState* state){V value;BoundaryProjectionWriter writer(value);auto checked=writer.object("",[&](auto& out){return emit_growth_tactic_lesson_fact_payloads_fields(out,c,state);});if(checked.ok)checked=writer.finish();return {checked.ok,std::move(value),checked.error};}
Outcome<V> growth_tactic_lesson_action_payloads(const CommonStore& c,const GrowthTacticLessonState* state){V value;BoundaryProjectionWriter writer(value);auto checked=writer.object("",[&](auto& out){return emit_growth_tactic_lesson_action_payloads_fields(out,c,state);});if(checked.ok)checked=writer.finish();return {checked.ok,std::move(value),checked.error};}
Status validate_growth_tactic_lesson_json_payloads(const CommonStore& c,const GrowthTacticLessonState* state,const V& source){try{using namespace boundary;unique(source);auto facts=growth_tactic_lesson_fact_payloads(c,state);if(!facts.ok)return {false,{},facts.error};for(const auto& row:object(facts.value,"tactic_lessons/facts")){const auto& actual=field(field(source,"facts","state"),row.first,"facts");if(!compare_boundary(actual,row.second).exact())return common_failure("TacticLessonFactPayloadMismatch",row.first);}auto actions=growth_tactic_lesson_action_payloads(c,state);if(!actions.ok)return {false,{},actions.error};for(const auto& row:object(actions.value,"tactic_lessons/actions")){const auto& actual=field(field(field(source,"actions","state"),row.first,"actions"),"params",row.first);if(!compare_boundary(actual,row.second).exact())return common_failure("TacticLessonActionPayloadMismatch",row.first);}return common_success();}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
BoundaryValue encode_growth_tactic_lesson_quote(const GrowthTacticLessonCommandQuote& quote){using namespace boundary;if(quote.kind=="tactic_lesson_start"&&quote.enrollment&&!quote.cancellation){const auto& s=quote.enrollment->agreement;return obj({{"duration",V{s.duration}},{"cost",V{s.total_fee}},{"tactic_id",V{s.tactic_id}},{"student_actor_id",V{s.student_id}},{"teacher_actor_id",V{s.teacher_id}},{"payment_policy",V{"reserve_then_pay_actual_teaching"}}});}if(quote.kind=="tactic_lesson_cancel"&&quote.cancellation&&!quote.enrollment){const auto& q=*quote.cancellation;return obj({{"duration",V{Integer{0}}},{"cost",V{Integer{0}}},{"action_id",V{q.action_id}},{"provided_half_days",V{q.provided_half_days}},{"fee_paid",V{q.fee_paid}},{"fee_released",V{q.fee_released}}});}boundary::fail("InvalidTacticLessonQuote",quote.kind);}
}
